-- Disposable baseline-event database required; never a live-project cleanup script.
do $$ begin if current_setting('app.continuity_test',true) is distinct from 'isolated' then raise exception 'Disposable continuity fixture required'; end if; end $$;
set role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',false);
select public.admin_save_event_organization(null,'IT','IT Organization',true,null);
