select continuity_test.assert('binding preserves all four approval states',(select array_agg(metadata->>'status' order by id)=array['draft','pending','disapproved','approved'] from map_elements where element_type='event_overlay' and metadata->>'title' like 'Legacy %'));
select continuity_test.assert('binding is relational',(select count(*)=5 from map_elements where organization_id=(select id from event_organizations where code='IT')));
select continuity_test.assert('binding preserves existing content revision numbers',(select count(*)=4 from map_elements where metadata->>'title' like 'Legacy %' and metadata->>'revision'='4'));
select continuity_test.assert('binding keeps original revision history and adds no fake edit rows',(select count(*)=5 from event_layout_revisions where event_id in (select id from map_elements where metadata->>'title' like 'Legacy %' or id='20000000-0000-0000-0000-000000000007')));
select public.save_campus_structure('10000000-0000-0000-0000-000000000001','{"map_elements":[{"id":"20000000-0000-0000-0000-000000000005","element_type":"tree","name":"Moved campus tree","x":25},{"id":"20000000-0000-0000-0000-000000000001","element_type":"event_overlay","name":"Tampered draft","metadata":{"kind":"event_overlay","status":"approved"}},{"id":"20000000-0000-0000-0000-000000000002","element_type":"custom","name":"Tampered pending","metadata":{"kind":"event_overlay","status":"draft"}}]}'::jsonb);
select continuity_test.assert('generic campus save still updates non-event map elements',(select name='Moved campus tree' and x=25 from map_elements where id='20000000-0000-0000-0000-000000000005'));
select continuity_test.assert('generic campus save leaves bound event records unchanged',(select count(*)=6 from map_elements where element_type='event_overlay' or metadata->>'kind'='event_overlay') and (select metadata->>'status'='draft' and name='Legacy draft' from map_elements where id='20000000-0000-0000-0000-000000000001'));
