select public.admin_set_event_representative((select id from event_organizations where code='IT'),'00000000-0000-0000-0000-000000000003','2026–2027',clock_timestamp()+interval '1 year',(select id from event_organization_grants where organization_id=(select id from event_organizations where code='IT') and ended_at is null));
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000002',false);
