select continuity_test.assert('outgoing cannot directly read revision history',(select count(*)=0 from event_layout_revisions));
select continuity_test.denied('outgoing revision RPC denied',$q$select public.list_event_revisions('20000000-0000-0000-0000-000000000001')$q$);
