select continuity_test.denied('legacy pending-save RPC cannot skip the current representative token',$q$select public.save_pending_event_layout('20000000-0000-0000-0000-000000000002',(select updated_at from map_elements where id='20000000-0000-0000-0000-000000000002'),(select metadata->'locations' from map_elements where id='20000000-0000-0000-0000-000000000002'))$q$);
select continuity_test.denied('pending organization event cannot be deleted',$q$select public.mutate_organization_event('20000000-0000-0000-0000-000000000002',(select updated_at from map_elements where id='20000000-0000-0000-0000-000000000002'),(select grant_id from get_my_event_organizations()),'delete','{}')$q$,'42501');
select public.mutate_organization_event('20000000-0000-0000-0000-000000000002',(select updated_at from map_elements where id='20000000-0000-0000-0000-000000000002'),(select grant_id from get_my_event_organizations()),'layout',jsonb_build_object('locations',(select metadata->'locations' from map_elements where id='20000000-0000-0000-0000-000000000002')));
select continuity_test.assert('successor pending save retains pending status',(select metadata->>'status'='pending' from map_elements where id='20000000-0000-0000-0000-000000000002'));
select continuity_test.denied('legacy feedback RPC cannot skip the current representative token',$q$select public.set_event_feedback_pin_addressed('20000000-0000-0000-0000-000000000004',(select updated_at from map_elements where id='20000000-0000-0000-0000-000000000004'),'campus-grounds','pin-1',true,'Checked')$q$);
select public.set_organization_event_feedback_pin_addressed('20000000-0000-0000-0000-000000000004',(select updated_at from map_elements where id='20000000-0000-0000-0000-000000000004'),(select grant_id from get_my_event_organizations()),'campus-grounds','pin-1',true,'Checked');
