select continuity_test.denied('approved layout remains locked',$q$select public.mutate_organization_event('20000000-0000-0000-0000-000000000004',(select updated_at from map_elements where id='20000000-0000-0000-0000-000000000004'),(select grant_id from get_my_event_organizations()),'details','{"title":"Bypass approval"}')$q$);
select continuity_test.denied('approved organization event cannot be deleted',$q$select public.mutate_organization_event('20000000-0000-0000-0000-000000000004',(select updated_at from map_elements where id='20000000-0000-0000-0000-000000000004'),(select grant_id from get_my_event_organizations()),'delete','{}')$q$,'42501');
