select continuity_test.denied('successor cannot change original creator',$q$select public.mutate_organization_event('20000000-0000-0000-0000-000000000001',(select updated_at from map_elements where id='20000000-0000-0000-0000-000000000001'),(select grant_id from get_my_event_organizations()),'details','{"createdByUserId":"00000000-0000-0000-0000-000000000003"}')$q$);
