select continuity_test.denied('new event rejects a non-text description before insertion',$q$select public.create_organization_event('30000000-0000-0000-0000-000000000002',(select organization_id from get_my_event_organizations()),(select grant_id from get_my_event_organizations()),'10000000-0000-0000-0000-000000000001','2026–2027','{"title":"Invalid description","description":{"html":"<script>"},"locations":[{"id":"campus-grounds","locationRef":{"type":"campus","label":"Campus Grounds"},"eventFurniture":[],"eventLabels":[]}]}'::jsonb)$q$,'23514');
